<?php require_once __DIR__ . '/koneksi.php'; if(isset($_POST['tambah'])){$q=$pdo->prepare('INSERT INTO dokter(nama_dokter,spesialis,no_hp) VALUES(?,?,?)');$q->execute([$_POST['nama'],$_POST['spesialis'],$_POST['hp']]);header('Location:dokter.php');exit;} if(isset($_GET['hapus'])){$q=$pdo->prepare('DELETE FROM dokter WHERE id=?');$q->execute([(int)$_GET['hapus']]);header('Location:dokter.php');exit;} $rows=$pdo->query('SELECT * FROM dokter')->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="assets/style.css"></head><body><main class="wrap"><h1>KlinikZakwan</h1><h2>Data Dokter</h2><form method="post"><label>Nama dokter</label><input name="nama" required><label>Spesialis</label><input name="spesialis" required><label>No. HP</label><input name="hp" required><button name="tambah">Tambah Dokter</button></form><table class="table"><tr><th>ID</th><th>Nama dokter</th><th>Spesialis</th><th>No. HP</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=htmlspecialchars($r['nama_dokter'])?></td><td><?=htmlspecialchars($r['spesialis'])?></td><td><?=htmlspecialchars($r['no_hp'])?></td><td><a href="?hapus=<?=$r['id']?>">Hapus</a></td></tr><?php endforeach;?></table><a href="index.php">Kembali</a></main></body></html>